// Since Rust doesn't have a built-in 'nat' type, we'll use u32 as a reasonable
// representation for natural numbers (non-negative integers)
type nat = u32;

fn find_smallest(s: &Vec<nat>) -> Option<nat> {
    // Handle empty array case
    if s.is_empty() {
        return None;
    }
    
    // Initialize with the first element
    let mut smallest = s[0];
    
    // Iterate through the rest of the array
    for &num in s.iter().skip(1) {
        if num < smallest {
            smallest = num;
        }
    }
    
    Some(smallest)
}

// Example usage and tests
fn main() {
    // Test cases
    let empty: Vec<nat> = vec![];
    let single = vec![5];
    let multiple = vec![3, 1, 4, 1, 5, 9];
    let all_same = vec![7, 7, 7, 7];
    let large_numbers = vec![100, 99, 101, 98, 102];
    
    assert_eq!(find_smallest(&empty), None);
    assert_eq!(find_smallest(&single), Some(5));
    assert_eq!(find_smallest(&multiple), Some(1));
    assert_eq!(find_smallest(&all_same), Some(7));
    assert_eq!(find_smallest(&large_numbers), Some(98));
    
    println!("All tests passed!");
}